TUTORIALS.append({'title': 'HIS-1. Setup: what changed, layout, urls', 'category': 'programming', 'order': 1, 'summary': 'Do this first: what was fixed, the file layout and the url names.', 'content': '<p>Step 1 of 6. The <code>history</code> app already exists at work: replace its files with the ones in the next lessons. No models, no migrations, no new packages.</p>\n<h3>What was wrong</h3>\n<p>«Удалить выбранные» also ran the auto-cleanup (the view never read which button was pressed), and the checkbox sent only the file name, so a same-named file in another folder was deleted too. Now the checkbox sends <code>folder/file</code> and each button does only its own job.</p>\n<h3>Layout</h3>\n<pre><code class="language-plaintext">history/\n    views.py\n    urls.py\n    templates/history/_file_card.html\n    templates/history/home.html\n    templates/history/datasets.html\n</code></pre>\n<p>If your templates live in the project-level <code>templates/history/</code> folder, put the three <code>.html</code> files there instead.</p>\n<h3>urls.py of the project</h3>\n<p>Either include the app urls, or keep your own routes and make sure the names match (<code>history</code> is where cleanup returns; <code>datasets-files</code> is new):</p>\n<pre><code class="language-python">path("history/", include("history.urls")),\n</code></pre>\n<pre><code class="language-plaintext">sudo systemctl restart gunicorn\n</code></pre>\n'})

TUTORIALS.append({'title': 'HIS-2. views.py', 'category': 'programming', 'order': 2, 'summary': 'Downloads, the fixed cleanup (selected deletes ONLY the ticked files; auto runs only on its own button) and the admin page with every file in datasets/.', 'content': '<p>Step 2 of 6. Save as <code>history/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">from django.shortcuts import render, redirect\nimport os\nimport re\nfrom datetime import datetime, timedelta\nfrom django.http import FileResponse, Http404, HttpResponse\nfrom io import BytesIO\nimport pandas as pd\n\nfrom django.contrib.auth.decorators import login_required\nfrom django.contrib import messages\nfrom pathlib import Path\nfrom functions import common_choices\n\nBASE_DIR = Path(__file__).resolve().parent.parent\ndatasets_folder = BASE_DIR / "datasets"\nportfel_input_folder = datasets_folder / "portfel" / "input"\nportfel_svod_folder = datasets_folder / "portfel" / "svod"\nportfel_all_folder = datasets_folder / "portfel" / "all"\nbalans_svod_folder = datasets_folder / "balans" / "svod"\ndynamics_summary_folder = datasets_folder / "dynamics" / "summary"\n\n\n# ---------------------------------------------------------------- helpers\n\ndef list_files(folder):\n    """Files of one folder, newest name first.\n    Each item: name (shown, without .parquet) and path (relative to datasets,\n    e.g. \'portfel/svod/svod_2026-11-01.parquet\') - the path is what the\n    checkbox sends, so a file is always found in ITS folder only."""\n    if not folder.exists():\n        return []\n    files = []\n    for f in sorted(folder.glob("*.parquet"), reverse=True):\n        files.append({\n            \'name\': f.stem,\n            \'path\': f.relative_to(datasets_folder).as_posix(),\n        })\n    return files\n\n\ndef safe_file(relative_path):\n    """Turn \'portfel/svod/x.parquet\' into a real path, but ONLY if it is a\n    file inside the datasets folder. Anything else (../, missing) -&gt; None."""\n    path = (datasets_folder / relative_path).resolve()\n    if datasets_folder.resolve() not in path.parents:\n        return None\n    if not path.is_file():\n        return None\n    return path\n\n\ndef delete_files(relative_paths):\n    """Delete the given files. Returns how many were deleted."""\n    deleted = 0\n    for rel in relative_paths:\n        path = safe_file(rel)\n        if path is None:\n            continue\n        try:\n            path.unlink()\n            deleted += 1\n        except OSError:\n            pass\n    return deleted\n\n\n# ---------------------------------------------------------------- pages\n\n@login_required\ndef home(request):\n    context = {\n        \'portfels_raw\': list_files(portfel_input_folder),\n        \'portfels_all\': list_files(portfel_all_folder),\n        \'portfels_svod\': list_files(portfel_svod_folder),\n        \'balans_svod\': list_files(balans_svod_folder),\n    }\n    return render(request, \'history/home.html\', context)\n\n\n@login_required\ndef download_file(request, filename):\n    filename = f"{filename}.parquet"\n    if "balans" in filename:\n        csv_filepath = os.path.join(balans_svod_folder, filename)\n    elif "svod" in filename:\n        csv_filepath = os.path.join(portfel_svod_folder, filename)\n    elif "all" in filename:\n        csv_filepath = os.path.join(portfel_all_folder, filename)\n    elif "raw" in filename:\n        csv_filepath = os.path.join(portfel_input_folder, filename)\n    else:\n        raise Http404("File not found")\n    if not os.path.exists(csv_filepath):\n        raise Http404("File not found")\n\n    df = pd.read_parquet(csv_filepath)\n    excel_buffer = BytesIO()\n    df.to_excel(excel_buffer, index=False, engine=\'openpyxl\')\n    excel_buffer.seek(0)\n\n    response = FileResponse(excel_buffer, as_attachment=True, filename=f"{os.path.splitext(filename)[0]}.xlsx")\n    response[\'Content-Type\'] = \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\'\n    return response\n\n\n@login_required\ndef export_model_to_excel(request):\n    filename = \'summary.parquet\'\n    file_full = f"{dynamics_summary_folder}/{filename}"\n    df = pd.read_parquet(file_full)\n\n    response = HttpResponse(content_type=\'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\')\n    response[\'Content-Disposition\'] = \'attachment; filename=all_summary_data.xlsx\'\n    df.to_excel(response, index=False)\n    return response\n\n\n@login_required\ndef cleanup_old_portfels(request):\n    if not request.user.is_staff:\n        messages.error(request, "У вас нет прав для выполнения этой операции.")\n        return redirect(\'history\')\n    if request.method != "POST":\n        return redirect(\'history\')\n\n    action = request.POST.get(\'action\')\n\n    # Button 1: «Удалить выбранные» - delete ONLY the ticked files\n    if action == \'selected\':\n        selected = request.POST.getlist(\'selected_files\')\n        if not selected:\n            messages.warning(request, "Ничего не выбрано.")\n            return redirect(\'history\')\n        deleted = delete_files(selected)\n        messages.success(request, f"Удалено выбранных файлов: {deleted}")\n        return redirect(\'history\')\n\n    # Button 2: «Авто-очистка» - older than 7 days and not a month-end\n    if action == \'auto\':\n        folders = [portfel_input_folder, portfel_svod_folder, portfel_all_folder, balans_svod_folder]\n        month_ends = {datetime.strptime(d, "%d.%m.%Y").date() for d in common_choices.official_month_ends}\n        one_week_ago = datetime.now().date() - timedelta(days=7)\n        date_pattern = re.compile(r\'\\d{4}-\\d{2}-\\d{2}\')\n\n        to_delete = []\n        for folder in folders:\n            if not folder.exists():\n                continue\n            for file_path in folder.glob("*.parquet"):\n                match = date_pattern.search(file_path.name)\n                if not match:\n                    continue  # no date in the name -&gt; never auto-deleted\n                try:\n                    file_date = datetime.strptime(match.group(), "%Y-%m-%d").date()\n                except ValueError:\n                    continue\n                if file_date &lt; one_week_ago and file_date not in month_ends:\n                    to_delete.append(file_path.relative_to(datasets_folder).as_posix())\n\n        deleted = delete_files(to_delete)\n        messages.success(request, f"Авто-очистка завершена. Удалено файлов: {deleted}")\n        return redirect(\'history\')\n\n    messages.error(request, "Неизвестное действие.")\n    return redirect(\'history\')\n\n\n# ---------------------------------------------------------------- admin: every file in datasets/\n\n@login_required\ndef datasets_files(request):\n    """Admin only: every file inside datasets/ (all sub-folders), grouped by\n    folder, with size and date. Tick any files and delete them."""\n    if not request.user.is_staff:\n        messages.error(request, "У вас нет прав для просмотра этой страницы.")\n        return redirect(\'history\')\n\n    if request.method == "POST":\n        selected = request.POST.getlist(\'selected_files\')\n        if not selected:\n            messages.warning(request, "Ничего не выбрано.")\n        else:\n            deleted = delete_files(selected)\n            messages.success(request, f"Удалено файлов: {deleted}")\n        return redirect(\'datasets-files\')\n\n    # { \'portfel/svod\': [file, file, ...], \'balans/svod\': [...], ... }\n    folders = {}\n    total_size = 0\n    for f in sorted(datasets_folder.rglob("*")):\n        if not f.is_file():\n            continue\n        stat = f.stat()\n        total_size += stat.st_size\n        folder_name = f.parent.relative_to(datasets_folder).as_posix()\n        if folder_name == \'.\':\n            folder_name = \'(корень datasets)\'\n        folders.setdefault(folder_name, []).append({\n            \'name\': f.name,\n            \'path\': f.relative_to(datasets_folder).as_posix(),\n            \'size_mb\': round(stat.st_size / 1024 / 1024, 2),\n            \'modified\': datetime.fromtimestamp(stat.st_mtime),\n        })\n\n    # newest files on top inside each folder\n    for files in folders.values():\n        files.sort(key=lambda x: x[\'modified\'], reverse=True)\n\n    context = {\n        \'folders\': folders,\n        \'total_files\': sum(len(v) for v in folders.values()),\n        \'total_size_mb\': round(total_size / 1024 / 1024, 1),\n    }\n    return render(request, \'history/datasets.html\', context)\n</code></pre>\n'})

TUTORIALS.append({'title': 'HIS-3. urls.py', 'category': 'programming', 'order': 3, 'summary': 'Route names: history, download-file, export-model-to-excel, cleanup-portfels, datasets-files.', 'content': '<p>Step 3 of 6. Save as <code>history/urls.py</code>.</p>\n<h3>urls.py</h3>\n<pre><code class="language-python">from django.urls import path\nfrom . import views\n\n# If your project already has these routes, just make sure the NAMES match:\n#   \'history\'          -&gt; the history page (cleanup redirects back here)\n#   \'datasets-files\'   -&gt; NEW: admin page with every file in datasets/\nurlpatterns = [\n    path(\'\', views.home, name=\'history\'),\n    path(\'download/&lt;str:filename&gt;/\', views.download_file, name=\'download-file\'),\n    path(\'export-summary/\', views.export_model_to_excel, name=\'export-model-to-excel\'),\n    path(\'cleanup/\', views.cleanup_old_portfels, name=\'cleanup-portfels\'),\n    path(\'datasets/\', views.datasets_files, name=\'datasets-files\'),\n]\n</code></pre>\n'})

TUTORIALS.append({'title': 'HIS-4. templates/history/_file_card.html', 'category': 'programming', 'order': 4, 'summary': 'One column of files with download buttons and admin checkboxes; used four times by home.html.', 'content': '<p>Step 4 of 6. Save as <code>history/templates/history/_file_card.html</code>.</p>\n<h3>templates/history/_file_card.html</h3>\n<pre><code class="language-html">{# One column of files. Used 4 times by home.html. #}\n&lt;div class="col-md-6 col-xl-3"&gt;\n    &lt;div class="card mb-3 h-100"&gt;\n        &lt;div class="card-header bg-{{ color }} text-white d-flex justify-content-between align-items-center"&gt;\n            &lt;h6 class="mb-0"&gt;{{ title }}&lt;/h6&gt;\n            &lt;span class="badge bg-light text-dark"&gt;{{ files|length }}&lt;/span&gt;\n        &lt;/div&gt;\n        &lt;div class="card-body" style="max-height: 500px; overflow-y: auto;"&gt;\n            {% for f in files %}\n            &lt;div class="mb-2 p-2 border rounded d-flex justify-content-between align-items-center"&gt;\n                &lt;div&gt;\n                    &lt;p class="mb-1 text-break small fw-semibold"&gt;{{ f.name }}&lt;/p&gt;\n                    &lt;a href="{% url \'download-file\' f.name %}" class="btn btn-{{ color }} btn-sm"&gt;\n                        &lt;i class="fa-solid fa-file-excel"&gt;&lt;/i&gt; Скачать\n                    &lt;/a&gt;\n                &lt;/div&gt;\n                {% if request.user.is_staff %}\n                {# value = folder + file, so only THIS file is deleted #}\n                &lt;input type="checkbox" name="selected_files" value="{{ f.path }}"\n                       class="form-check-input ms-2 border-danger" style="width:1.3em;height:1.3em;"\n                       title="Отметить для удаления"&gt;\n                {% endif %}\n            &lt;/div&gt;\n            {% empty %}\n            &lt;p class="text-muted"&gt;Нет доступных файлов.&lt;/p&gt;\n            {% endfor %}\n        &lt;/div&gt;\n    &lt;/div&gt;\n&lt;/div&gt;\n</code></pre>\n'})

TUTORIALS.append({'title': 'HIS-5. templates/history/home.html', 'category': 'programming', 'order': 5, 'summary': 'The history page: four file columns, admin cleanup panel, link to the file manager. Russian UI.', 'content': '<p>Step 5 of 6. Save as <code>history/templates/history/home.html</code>.</p>\n<h3>templates/history/home.html</h3>\n<pre><code class="language-html">{% extends \'base.html\' %}\n{% block content %}\n&lt;div class="container-fluid mt-4"&gt;\n    &lt;h1 class="page-header"&gt;Отчёты и данные&lt;/h1&gt;\n\n    {% if messages %}\n        {% for message in messages %}\n            &lt;div class="alert alert-{{ message.tags }} alert-dismissible fade show" role="alert"&gt;\n                {{ message }}\n                &lt;button type="button" class="btn-close" data-bs-dismiss="alert"&gt;&lt;/button&gt;\n            &lt;/div&gt;\n        {% endfor %}\n    {% endif %}\n\n    &lt;div class="alert alert-info mb-4"&gt;\n        &lt;h5&gt;Описание страницы&lt;/h5&gt;\n        &lt;p class="mb-0"&gt;\n            На этой странице вы можете скачать отчёты и данные по кредитным портфелям.&lt;br&gt;\n            &lt;strong&gt;Портфель → Исходные данные&lt;/strong&gt; — необработанные данные, загруженные из базы данных.&lt;br&gt;\n            &lt;strong&gt;Портфель → Готовые данные&lt;/strong&gt; — обработанные данные.&lt;br&gt;\n            &lt;strong&gt;Портфель → Готовые свод&lt;/strong&gt; — сводные данные по кредитным портфелям для анализа.&lt;br&gt;\n            &lt;strong&gt;Баланс против Портфель&lt;/strong&gt; — сравнительная таблица балансов и портфеля.&lt;br&gt;\n            &lt;strong&gt;Свод Преса&lt;/strong&gt; — все сводные данные, начиная с 2023 года.\n        &lt;/p&gt;\n    &lt;/div&gt;\n\n    &lt;form action="{% url \'cleanup-portfels\' %}" method="POST"&gt;\n        {% csrf_token %}\n\n        {% if request.user.is_staff %}\n        &lt;div class="card border-danger mb-4"&gt;\n            &lt;div class="card-header bg-danger text-white"&gt;\n                &lt;h5 class="mb-0"&gt;&lt;i class="fa-solid fa-triangle-exclamation"&gt;&lt;/i&gt; Панель администратора: очистка диска&lt;/h5&gt;\n            &lt;/div&gt;\n            &lt;div class="card-body"&gt;\n                &lt;p class="text-muted mb-3"&gt;\n                    &lt;strong&gt;«Удалить выбранные»&lt;/strong&gt; удаляет &lt;u&gt;только&lt;/u&gt; отмеченные галочками файлы.&lt;br&gt;\n                    &lt;strong&gt;«Авто-очистка»&lt;/strong&gt; удаляет файлы старше 7 дней, кроме отчётных дат (конец месяца).\n                &lt;/p&gt;\n                &lt;div class="d-flex flex-wrap gap-2"&gt;\n                    &lt;button type="submit" name="action" value="selected" class="btn btn-danger"\n                            onclick="return confirm(\'Удалить только отмеченные файлы?\');"&gt;\n                        &lt;i class="fa-solid fa-trash"&gt;&lt;/i&gt; Удалить выбранные\n                    &lt;/button&gt;\n                    &lt;button type="submit" name="action" value="auto" class="btn btn-outline-danger"\n                            onclick="return confirm(\'Удалить все файлы старше 7 дней (кроме отчётных дат)? Это необратимо.\');"&gt;\n                        &lt;i class="fa-solid fa-wand-magic-sparkles"&gt;&lt;/i&gt; Авто-очистка устаревших\n                    &lt;/button&gt;\n                    &lt;a href="{% url \'datasets-files\' %}" class="btn btn-outline-dark ms-auto"&gt;\n                        &lt;i class="fa-solid fa-folder-open"&gt;&lt;/i&gt; Все файлы в datasets\n                    &lt;/a&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n        {% endif %}\n\n        &lt;div class="row g-3"&gt;\n            {% include \'history/_file_card.html\' with title=\'Портфель → Исходные данные\' files=portfels_raw color=\'warning\' %}\n            {% include \'history/_file_card.html\' with title=\'Портфель → Готовые данные\' files=portfels_all color=\'success\' %}\n            {% include \'history/_file_card.html\' with title=\'Портфель → Готовые свод\' files=portfels_svod color=\'info\' %}\n            {% include \'history/_file_card.html\' with title=\'Баланс против Портфель\' files=balans_svod color=\'danger\' %}\n        &lt;/div&gt;\n    &lt;/form&gt;\n\n    &lt;div class="row mt-4 mb-5"&gt;\n        &lt;div class="col-12 text-center"&gt;\n            &lt;a href="{% url \'export-model-to-excel\' %}" class="btn btn-success btn-lg"&gt;\n                &lt;i class="fa-solid fa-file-excel"&gt;&lt;/i&gt; Скачать Свод Преса (Excel)\n            &lt;/a&gt;\n            &lt;p class="text-muted mt-2"&gt;Все сводные данные, начиная с 2023 года.&lt;/p&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'HIS-6. templates/history/datasets.html', 'category': 'programming', 'order': 6, 'summary': 'Admin only: every file in datasets/ grouped by folder with size and date; tick and delete. Russian UI.', 'content': '<p>Step 6 of 6. Save as <code>history/templates/history/datasets.html</code>.</p>\n<h3>templates/history/datasets.html</h3>\n<pre><code class="language-html">{% extends \'base.html\' %}\n{% block content %}\n&lt;div class="container-fluid mt-4"&gt;\n    &lt;div class="d-flex flex-wrap justify-content-between align-items-center mb-3 gap-2"&gt;\n        &lt;h1 class="page-header mb-0"&gt;Все файлы в datasets&lt;/h1&gt;\n        &lt;a href="{% url \'history\' %}" class="btn btn-outline-secondary"&gt;\n            &lt;i class="fa-solid fa-arrow-left"&gt;&lt;/i&gt; Назад к отчётам\n        &lt;/a&gt;\n    &lt;/div&gt;\n\n    {% if messages %}\n        {% for message in messages %}\n            &lt;div class="alert alert-{{ message.tags }} alert-dismissible fade show" role="alert"&gt;\n                {{ message }}\n                &lt;button type="button" class="btn-close" data-bs-dismiss="alert"&gt;&lt;/button&gt;\n            &lt;/div&gt;\n        {% endfor %}\n    {% endif %}\n\n    &lt;div class="alert alert-warning"&gt;\n        &lt;i class="fa-solid fa-triangle-exclamation"&gt;&lt;/i&gt;\n        Только для администратора. Всего файлов: &lt;strong&gt;{{ total_files }}&lt;/strong&gt;,\n        общий размер: &lt;strong&gt;{{ total_size_mb }} МБ&lt;/strong&gt;.\n        Отметьте файлы галочками и нажмите &lt;strong&gt;«Удалить выбранные»&lt;/strong&gt;. Удаление необратимо.\n    &lt;/div&gt;\n\n    &lt;form method="POST"&gt;\n        {% csrf_token %}\n\n        {# sticky button so it is always visible while scrolling #}\n        &lt;div class="sticky-top bg-white py-2 mb-3 border-bottom"&gt;\n            &lt;button type="submit" class="btn btn-danger"\n                    onclick="return confirm(\'Удалить отмеченные файлы? Это необратимо.\');"&gt;\n                &lt;i class="fa-solid fa-trash"&gt;&lt;/i&gt; Удалить выбранные\n            &lt;/button&gt;\n        &lt;/div&gt;\n\n        {% for folder, files in folders.items %}\n        &lt;div class="card mb-4"&gt;\n            &lt;div class="card-header d-flex justify-content-between align-items-center"&gt;\n                &lt;h6 class="mb-0"&gt;&lt;i class="fa-solid fa-folder text-warning"&gt;&lt;/i&gt; datasets/{{ folder }}&lt;/h6&gt;\n                &lt;span class="badge bg-secondary"&gt;{{ files|length }} файл(ов)&lt;/span&gt;\n            &lt;/div&gt;\n            &lt;div class="table-responsive" style="max-height: 420px; overflow-y: auto;"&gt;\n                &lt;table class="table table-sm table-hover align-middle mb-0"&gt;\n                    &lt;thead class="table-light" style="position: sticky; top: 0;"&gt;\n                        &lt;tr&gt;\n                            &lt;th style="width: 40px;"&gt;&lt;/th&gt;\n                            &lt;th&gt;Файл&lt;/th&gt;\n                            &lt;th class="text-end"&gt;Размер, МБ&lt;/th&gt;\n                            &lt;th class="text-end"&gt;Изменён&lt;/th&gt;\n                        &lt;/tr&gt;\n                    &lt;/thead&gt;\n                    &lt;tbody&gt;\n                        {% for f in files %}\n                        &lt;tr&gt;\n                            &lt;td&gt;\n                                &lt;input type="checkbox" name="selected_files" value="{{ f.path }}"\n                                       id="f{{ forloop.parentloop.counter }}_{{ forloop.counter }}"\n                                       class="form-check-input border-danger"&gt;\n                            &lt;/td&gt;\n                            &lt;td&gt;\n                                &lt;label for="f{{ forloop.parentloop.counter }}_{{ forloop.counter }}" class="text-break mb-0"&gt;\n                                    {{ f.name }}\n                                &lt;/label&gt;\n                            &lt;/td&gt;\n                            &lt;td class="text-end"&gt;{{ f.size_mb }}&lt;/td&gt;\n                            &lt;td class="text-end text-nowrap"&gt;{{ f.modified|date:"d.m.Y H:i" }}&lt;/td&gt;\n                        &lt;/tr&gt;\n                        {% endfor %}\n                    &lt;/tbody&gt;\n                &lt;/table&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n        {% empty %}\n        &lt;p class="text-muted"&gt;Папка datasets пуста.&lt;/p&gt;\n        {% endfor %}\n    &lt;/form&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})
